def verify(witness):
    if witness.get('kind') != 'omega_window_check':
        return False
    if witness.get('k_min') != 2 or witness.get('k_max') != 6 or witness.get('n_max') != 2000:
        return False
    if witness.get('window') != '(n, n+P_k], P_k=product of first k primes, Omega with multiplicity':
        return False
    if witness.get('predicate') != 'for every k in {2,3,4,5,6} and every n with 2^k <= n <= 2000: exists m in {n+1,...,n+P_k} with Omega(m) > k':
        return False
    NMAX = 2000
    PK = {2: 6, 3: 30, 4: 210, 5: 2310, 6: 30030}
    LIMIT = NMAX + PK[6]
    spf = list(range(LIMIT + 1))
    i = 2
    while i * i <= LIMIT:
        if spf[i] == i:
            for j in range(i * i, LIMIT + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    om = [0] * (LIMIT + 1)
    for m in range(2, LIMIT + 1):
        om[m] = om[m // spf[m]] + 1
    ps = []
    v = 2
    while len(ps) < 6:
        is_prime = True
        for d in range(2, v):
            if v % d == 0:
                is_prime = False
                break
        if is_prime:
            ps.append(v)
        v += 1
    for k in range(2, 7):
        pr = 1
        for t in range(k):
            pr *= ps[t]
        if pr != PK[k]:
            return False
    for k in range(2, 7):
        pk = PK[k]
        INF = LIMIT + 1
        nxt = [INF] * (LIMIT + 2)
        for m in range(LIMIT, 0, -1):
            if om[m] > k:
                nxt[m] = m
            else:
                nxt[m] = nxt[m + 1]
        for n in range(2 ** k, NMAX + 1):
            if nxt[n + 1] > n + pk:
                return False
    return True
